use super::*;

/// Top-level type names DEFINED in this module — struct / enum / type-alias / union in Rust,
/// interface / type-alias / enum / class in TypeScript. A leaf whose signature names one is a
/// method-in-disguise over the module's own data, not a free-standing helper.
///
/// ONE UNION OF NODE KINDS RATHER THAN A GRAMMAR BRANCH, because the two grammars' kinds do not
/// collide — neither language emits the other's spelling, so a kind that is absent simply never
/// matches. The `export_statement` unwrap is the one thing TypeScript genuinely needs: `export
/// interface Node {…}` is an `export_statement` WRAPPING the declaration, so without looking through it
/// every exported type would be invisible and a type-coupled module would read as a genuine collection.
/// Rust never emits an `export_statement`, so the unwrap is inert there.
pub(crate) fn module_defined_types(root: Node, src: &[u8]) -> std::collections::HashSet<String> {
    let mut names = std::collections::HashSet::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        let inner = if child.kind() == "export_statement" {
            child.child_by_field_name("declaration").unwrap_or(child)
        } else {
            child
        };
        if matches!(
            inner.kind(),
            "struct_item"
                | "enum_item"
                | "type_item"
                | "union_item"
                | "interface_declaration"
                | "type_alias_declaration"
                | "enum_declaration"
                | "class_declaration"
        ) {
            if let Some(n) = inner.child_by_field_name("name") {
                names.insert(n.utf8_text(src).unwrap_or_default().to_string());
            }
        }
    }
    names
}
